<script setup lang="ts">
import {ref} from 'vue'
import {Coins,ShoppingBag,Check,LockKeyhole} from 'lucide-vue-next'
import {itemIcons,type ShopState} from '../lib/shop'
defineProps<{shop:ShopState;coins:number;level:number;busy:boolean}>()
const emit=defineEmits<{action:[action:string,item:string]}>(),tab=ref('shop')
</script>
<template><section class="pet-shop"><header><ShoppingBag :size="22"/><h4>Su pequeño armario</h4></header><div class="shop-tabs"><button @click="tab='shop'" :aria-pressed="tab==='shop'">Tienda</button><button @click="tab='owned'" :aria-pressed="tab==='owned'">Mis cosas · {{shop.owned.length}}</button></div><p>Gana monedas jugando y dale tu toque. Todo se compra con monedas del juego.</p><div v-if="tab==='owned'" class="wardrobe-reset"><button :disabled="busy||!shop.style.accessory" @click="emit('action','accessory','')">Quitar accesorio</button><button :disabled="busy||!shop.style.theme" @click="emit('action','theme','')">Color original</button></div><div class="shop-grid"><article v-for="item in shop.catalog.filter(i=>tab==='shop'||shop.owned.includes(i.id))" :key="item.id"><span class="shop-icon" :class="item.id">{{itemIcons[item.id]}}</span><b>{{item.name}}</b><small>{{item.kind==='theme'?'Color de las habitaciones':'Accesorio del perrito'}}</small><button v-if="shop.owned.includes(item.id)" :disabled="busy||shop.style[item.kind]===item.id" @click="emit('action',item.kind,item.id)"><Check v-if="shop.style[item.kind]===item.id" :size="14"/>{{shop.style[item.kind]===item.id?'Puesto':'Usar'}}</button><button v-else :disabled="busy||level<item.level||coins<item.price" @click="emit('action','buy',item.id)"><template v-if="level<item.level"><LockKeyhole :size="13"/> Nivel {{item.level}}</template><template v-else><Coins :size="13"/> {{item.price}} · Comprar</template></button></article></div><p v-if="tab==='owned'&&!shop.owned.length">Aún no tienes accesorios. Tu primera compra te espera en la tienda.</p></section></template>
